1	// Package git wraps the git binary with the operations the deployment
2	// commands need. It is deliberately narrow: only what is used, and nothing
3	// that would tempt a caller into arbitrary git.
4	package git
5	
6	import (
7		"context"
8		"errors"
9		"fmt"
10		"strings"
11		"time"
12	
13		"github.com/integrio-intropy/intropy-cli/internal/command"
14	)
15	
16	// Client is a typed wrapper over the git binary rooted at a working directory.
17	type Client struct {
18		Runner command.Runner
19		Dir    string
20	}
21	
22	func (g Client) run(ctx context.Context, args ...string) (string, error) {
23		stdout, _, err := g.Runner.Run(ctx, g.Dir, "git", args...)
24		return strings.TrimSpace(string(stdout)), err
25	}
26	
27	// HEAD returns the full commit sha of HEAD. Full, not abbreviated: an
28	// abbreviated sha is ambiguous as a registry tag and as an ancestry argument.
29	func (g Client) HEAD(ctx context.Context) (string, error) {
30		sha, err := g.run(ctx, "rev-parse", "HEAD")
31		if err != nil {
32			return "", fmt.Errorf("resolve HEAD: %w", err)
33		}
34		return sha, nil
35	}
36	
37	// Status returns porcelain status lines limited to paths, or to the whole tree
38	// when no paths are given.
39	//
40	// Untracked files are listed individually rather than collapsed to their
41	// directory: these lines are shown to the user when a deploy is refused, and
42	// "component/" is a much less useful answer than the files that are actually
43	// uncommitted.
44	func (g Client) Status(ctx context.Context, paths ...string) ([]string, error) {
45		args := []string{"status", "--porcelain", "--untracked-files=all"}
46		if len(paths) > 0 {
47			args = append(args, "--")
48			args = append(args, paths...)
49		}
50		out, err := g.run(ctx, args...)
51		if err != nil {
52			return nil, fmt.Errorf("read working tree status: %w", err)
53		}
54		if out == "" {
55			return nil, nil
56		}
57		return strings.Split(out, "\n"), nil
58	}
59	
60	// Fetch updates remote-tracking refs. Callers that are about to reason about
61	// ancestry must fetch first: a stale origin/<branch> makes a pushed commit look
62	// unpushed.
63	func (g Client) Fetch(ctx context.Context, remote string, refspecs ...string) error {
64		args := append([]string{"fetch", "--quiet", remote}, refspecs...)
65		if _, err := g.run(ctx, args...); err != nil {
66			return fmt.Errorf("fetch %s: %w", remote, err)
67		}
68		return nil
69	}
70	
71	// DefaultBranch returns the remote's default branch name, preferring the
72	// symbolic ref that git records at clone time and falling back to querying the
73	// remote. Hardcoding "main" would be wrong for any repository that never
74	// renamed from master.
75	func (g Client) DefaultBranch(ctx context.Context, remote string) (string, error) {
76		if out, err := g.run(ctx, "symbolic-ref", "--short", "refs/remotes/"+remote+"/HEAD"); err == nil {
77			// refs/remotes/origin/HEAD reads back as "origin/main".
78			if _, branch, ok := strings.Cut(out, "/"); ok && branch != "" {
79				return branch, nil
80			}
81		}
82	
83		// Freshly cloned mirrors and worktrees created with --single-branch may
84		// have no origin/HEAD; ask the remote directly.
85		out, err := g.run(ctx, "ls-remote", "--symref", remote, "HEAD")
86		if err != nil {
87			return "", fmt.Errorf("determine default branch of %s: %w", remote, err)
88		}
89		for line := range strings.SplitSeq(out, "\n") {
90			// "ref: refs/heads/main\tHEAD"
91			rest, ok := strings.CutPrefix(strings.TrimSpace(line), "ref: refs/heads/")
92			if !ok {
93				continue
94			}
95			if branch, _, _ := strings.Cut(rest, "\t"); branch != "" {
96				return branch, nil
97			}
98		}
99		return "", fmt.Errorf("determine default branch of %s: no symref in ls-remote output", remote)
100	}
101	
102	// IsAncestor reports whether ancestor is an ancestor of descendant. Equal
103	// commits count as ancestors, matching git's own semantics.
104	func (g Client) IsAncestor(ctx context.Context, ancestor, descendant string) (bool, error) {
105		_, err := g.run(ctx, "merge-base", "--is-ancestor", ancestor, descendant)
106		if err == nil {
107			return true, nil
108		}
109		// git exits 1 for "not an ancestor" and 128 for a bad revision, so only
110		// exit 1 may be read as a clean negative answer.
111		if ee, ok := errors.AsType[*command.ExitError](err); ok && ee.Code == 1 {
112			return false, nil
113		}
114		return false, fmt.Errorf("check whether %s is an ancestor of %s: %w", ShortSHA(ancestor), ShortSHA(descendant), err)
115	}
116	
117	// Add stages paths.
118	func (g Client) Add(ctx context.Context, paths ...string) error {
119		args := append([]string{"add", "--"}, paths...)
120		if _, err := g.run(ctx, args...); err != nil {
121			return fmt.Errorf("stage changes: %w", err)
122		}
123		return nil
124	}
125	
126	// CheckoutPaths discards working-tree changes under paths. Always pass an
127	// explicit path: an unscoped revert would throw away anything else in the
128	// worktree, including a concurrent run's staged work.
129	func (g Client) CheckoutPaths(ctx context.Context, paths ...string) error {
130		if len(paths) == 0 {
131			return errors.New("CheckoutPaths requires at least one path")
132		}
133		args := append([]string{"checkout", "--"}, paths...)
134		if _, err := g.run(ctx, args...); err != nil {
135			return fmt.Errorf("discard changes: %w", err)
136		}
137		return nil
138	}
139	
140	// CreateBranch creates name at startPoint and checks it out, resetting it if it
141	// already exists locally.
142	//
143	// The reset is deliberate: the only local branches in a cached checkout are ones
144	// a previous run of this CLI left behind, and reusing a stale one would build a
145	// commit on top of whatever that run happened to do.
146	func (g Client) CreateBranch(ctx context.Context, name, startPoint string) error {
147		if _, err := g.run(ctx, "checkout", "-B", name, startPoint); err != nil {
148			return fmt.Errorf("create branch %s at %s: %w", name, startPoint, err)
149		}
150		return nil
151	}
152	
153	// Switch checks out an existing ref.
154	//
155	// Callers holding a shared cached checkout must switch back to the default
156	// branch when they are done: the refresh on the next Open resets whatever branch
157	// is current to the default branch's remote head, which would silently discard a
158	// feature branch's commits.
159	func (g Client) Switch(ctx context.Context, ref string) error {
160		if _, err := g.run(ctx, "checkout", ref); err != nil {
161			return fmt.Errorf("switch to %s: %w", ref, err)
162		}
163		return nil
164	}
165	
166	// ResetHard moves the branch and working tree to ref.
167	func (g Client) ResetHard(ctx context.Context, ref string) error {
168		if _, err := g.run(ctx, "reset", "--hard", ref); err != nil {
169			return fmt.Errorf("reset to %s: %w", ref, err)
170		}
171		return nil
172	}
173	
174	// Clean removes untracked files and directories.
175	func (g Client) Clean(ctx context.Context) error {
176		if _, err := g.run(ctx, "clean", "-fdq"); err != nil {
177			return fmt.Errorf("clean working tree: %w", err)
178		}
179		return nil
180	}
181	
182	// RevParse resolves any revision expression to a full sha.
183	func (g Client) RevParse(ctx context.Context, rev string) (string, error) {
184		sha, err := g.run(ctx, "rev-parse", rev)
185		if err != nil {
186			return "", fmt.Errorf("resolve %s: %w", rev, err)
187		}
188		return sha, nil
189	}
190	
191	// Clone clones url into dir. dir must not already exist.
192	func Clone(ctx context.Context, r command.Runner, url, dir string) error {
193		if _, _, err := r.Run(ctx, "", "git", "clone", "--quiet", url, dir); err != nil {
194			return fmt.Errorf("clone %s: %w", url, err)
195		}
196		return nil
197	}
198	
199	// ShortSHA abbreviates a sha for messages, leaving non-sha revisions alone.
200	func ShortSHA(rev string) string {
201		if len(rev) >= 40 {
202			return rev[:7]
203		}
204		return rev
205	}
206	
207	// Commit records the staged changes. Each message becomes a paragraph, which is
208	// how a subject line and a trailer block are produced without a temporary file:
209	// git separates -m arguments with a blank line, and trailers only need to be
210	// the final paragraph to be parseable by `git log --format=%(trailers)`.
211	//
212	// Nothing is staged implicitly — there is no -a — so the caller decides exactly
213	// what the commit contains.
214	func (g Client) Commit(ctx context.Context, messages ...string) error {
215		if len(messages) == 0 {
216			return errors.New("Commit requires at least a subject")
217		}
218		args := []string{"commit", "--quiet"}
219		for _, m := range messages {
220			args = append(args, "-m", m)
221		}
222		if _, err := g.run(ctx, args...); err != nil {
223			return fmt.Errorf("commit: %w", err)
224		}
225		return nil
226	}
227	
228	// Tag creates an annotated tag at commit. Annotated rather than lightweight:
229	// it carries the author, date and message that make the tag worth reading in
230	// `git log`, which is the only reason the tag exists.
231	//
232	// Creating a tag that already exists is an error rather than a silent move —
233	// a release tag that quietly relocates would misrepresent history.
234	func (g Client) Tag(ctx context.Context, name, message, commit string) error {
235		if _, err := g.run(ctx, "tag", "--annotate", "--message", message, name, commit); err != nil {
236			return fmt.Errorf("tag %s: %w", name, err)
237		}
238		return nil
239	}
240	
241	// TagCommit resolves an annotated or lightweight tag to the commit it points
242	// at. The bool reports whether the tag exists locally at all, so a caller can
243	// tell "no such tag" from a genuine failure to read it.
244	func (g Client) TagCommit(ctx context.Context, name string) (string, bool, error) {
245		// ^{commit} dereferences an annotated tag to its commit; without it the
246		// answer would be the tag object's own sha, which never matches a commit.
247		sha, err := g.run(ctx, "rev-parse", "--verify", "--quiet", "refs/tags/"+name+"^{commit}")
248		if err == nil {
249			return sha, sha != "", nil
250		}
251		// --quiet makes an unknown ref exit 1 with no output, which is the answer
252		// rather than a failure.
253		if ee, ok := errors.AsType[*command.ExitError](err); ok && ee.Code == 1 {
254			return "", false, nil
255		}
256		return "", false, fmt.Errorf("resolve tag %s: %w", name, err)
257	}
258	
259	// LogCommit is one commit in a range, reduced to what release notes need.
260	type LogCommit struct {
261		SHA     string
262		Subject string
263	}
264	
265	// LastCommit returns the sha of the most recent commit on rev that changed path,
266	// and whether there was one.
267	//
268	// Merges are not excluded here, unlike Log: this answers "which commit put the
269	// file in its current state", and a merge that resolved the file really is that
270	// commit.
271	func (g Client) LastCommit(ctx context.Context, rev, path string) (string, bool, error) {
272		sha, _, found, err := g.LastCommitAt(ctx, rev, path)
273		return sha, found, err
274	}
275	
276	// LastCommitAt is LastCommit with the commit's timestamp, which is what dates a
277	// deployment: an overlay changed when the commit that changed it landed.
278	//
279	// The committer date rather than the author date. Publish rebases and retries
280	// when the push races another deployment, which rewrites the committer date and
281	// leaves the author date at the first attempt; the later of the two is when the
282	// change actually reached the branch.
283	func (g Client) LastCommitAt(ctx context.Context, rev, path string) (string, time.Time, bool, error) {
284		// NUL-separated for the same reason Log is: the fields are fixed-width here,
285		// but one delimiter convention in this file is one fewer thing to get wrong.
286		out, err := g.run(ctx, "log", "-1", "--format=%H%x00%cI", rev, "--", path)
287		if err != nil {
288			return "", time.Time{}, false, fmt.Errorf("read last commit for %s: %w", path, err)
289		}
290		if out == "" {
291			return "", time.Time{}, false, nil
292		}
293	
294		sha, date, ok := strings.Cut(out, "\x00")
295		if !ok {
296			return "", time.Time{}, false, fmt.Errorf("read last commit for %s: unexpected git log output %q", path, out)
297		}
298		at, err := time.Parse(time.RFC3339, date)
299		if err != nil {
300			return "", time.Time{}, false, fmt.Errorf("read last commit for %s: parse commit date %q: %w", path, date, err)
301		}
302		return sha, at, true, nil
303	}
304	
305	// Log lists the commits in revRange, most recent first, limited to paths when
306	// any are given.
307	//
308	// The two fields are separated by a NUL and the records by a newline: a commit
309	// subject may contain anything except a newline, so a printable delimiter
310	// could appear inside one and split a record in the wrong place.
311	func (g Client) Log(ctx context.Context, revRange string, paths ...string) ([]LogCommit, error) {
312		args := []string{"log", "--format=%H%x00%s", "--no-merges", revRange}
313		if len(paths) > 0 {
314			args = append(args, "--")
315			args = append(args, paths...)
316		}
317		out, err := g.run(ctx, args...)
318		if err != nil {
319			return nil, fmt.Errorf("read log for %s: %w", revRange, err)
320		}
321		if out == "" {
322			return nil, nil
323		}
324	
325		var commits []LogCommit
326		for line := range strings.SplitSeq(out, "\n") {
327			sha, subject, ok := strings.Cut(line, "\x00")
328			if !ok {
329				continue
330			}
331			commits = append(commits, LogCommit{SHA: sha, Subject: subject})
332		}
333		return commits, nil
334	}
335	
336	// Push pushes refspec to remote.
337	//
338	// A rejection is reported as *PushRejectedError so callers can rebase and retry,
339	// distinguished from an authentication or network failure where retrying is
340	// pointless.
341	func (g Client) Push(ctx context.Context, remote, refspec string) error {
342		_, err := g.run(ctx, "push", "--quiet", remote, refspec)
343		if err == nil {
344			return nil
345		}
346		if ee, ok := errors.AsType[*command.ExitError](err); ok && isRejection(ee.Stderr) {
347			return &PushRejectedError{Remote: remote, Refspec: refspec, Stderr: ee.Stderr}
348		}
349		return fmt.Errorf("push %s %s: %w", remote, refspec, err)
350	}
351	
352	// PushRejectedError reports that the remote refused the push because it has
353	// commits we do not have.
354	type PushRejectedError struct {
355		Remote  string
356		Refspec string
357		Stderr  string
358	}
359	
360	func (e *PushRejectedError) Error() string {
361		return fmt.Sprintf("push to %s was rejected: %s", e.Remote, strings.TrimSpace(e.Stderr))
362	}
363	
364	// isRejection recognises a non-fast-forward refusal. git has no distinct exit
365	// code for it, so the message is the only signal available; the phrases below
366	// are the ones git itself emits.
367	func isRejection(stderr string) bool {
368		for _, marker := range []string{"[rejected]", "non-fast-forward", "fetch first", "Updates were rejected"} {
369			if strings.Contains(stderr, marker) {
370				return true
371			}
372		}
373		return false
374	}
375	
376	// Rebase replays the current branch onto upstream.
377	//
378	// A conflict is reported as *RebaseConflictError with the rebase left in
379	// progress, so the caller can decide — this package must not abort on the
380	// caller's behalf, because whether a conflict is recoverable is policy.
381	func (g Client) Rebase(ctx context.Context, upstream string) error {
382		_, err := g.run(ctx, "rebase", upstream)
383		if err == nil {
384			return nil
385		}
386		if ee, ok := errors.AsType[*command.ExitError](err); ok {
387			return &RebaseConflictError{Upstream: upstream, Stderr: ee.Stderr}
388		}
389		return fmt.Errorf("rebase onto %s: %w", upstream, err)
390	}
391	
392	// RebaseConflictError reports a rebase that stopped, leaving the repository
393	// mid-rebase.
394	type RebaseConflictError struct {
395		Upstream string
396		Stderr   string
397	}
398	
399	func (e *RebaseConflictError) Error() string {
400		return fmt.Sprintf("rebase onto %s stopped: %s", e.Upstream, strings.TrimSpace(e.Stderr))
401	}
402	
403	// RebaseAbort restores the state from before a rebase.
404	func (g Client) RebaseAbort(ctx context.Context) error {
405		if _, err := g.run(ctx, "rebase", "--abort"); err != nil {
406			return fmt.Errorf("abort rebase: %w", err)
407		}
408		return nil
409	}
410	
411	// Trailers returns the trailer block of a commit message as ordered pairs.
412	// Duplicate keys are preserved, since a commit may legitimately repeat one.
413	func (g Client) Trailers(ctx context.Context, rev string) ([]Trailer, error) {
414		out, err := g.run(ctx, "log", "-1", "--format=%(trailers:only=true)", rev)
415		if err != nil {
416			return nil, fmt.Errorf("read trailers of %s: %w", ShortSHA(rev), err)
417		}
418		var trailers []Trailer
419		for line := range strings.SplitSeq(out, "\n") {
420			key, value, ok := strings.Cut(strings.TrimSpace(line), ":")
421			if !ok || key == "" {
422				continue
423			}
424			trailers = append(trailers, Trailer{Key: key, Value: strings.TrimSpace(value)})
425		}
426		return trailers, nil
427	}
428	
429	// Trailer is one Key: value line from a commit message's trailer block.
430	type Trailer struct {
431		Key   string
432		Value string
433	}
434	
435	// String renders the trailer as it appears in a commit message.
436	func (t Trailer) String() string { return t.Key + ": " + t.Value }
437

1	// Package gitops models the GitOps repository: a cached, locked checkout of
2	// it, the directory layout that locates a component, and the two contract
3	// files (deploy.yaml and component.yaml) that describe what may be deployed
4	// where.
5	package gitops
6	
7	import (
8		"context"
9		"crypto/sha256"
10		"encoding/hex"
11		"errors"
12		"fmt"
13		"io/fs"
14		"os"
15		"path/filepath"
16		"syscall"
17	
18		"github.com/integrio-intropy/intropy-cli/internal/command"
19		"github.com/integrio-intropy/intropy-cli/internal/config"
20		"github.com/integrio-intropy/intropy-cli/internal/git"
21	)
22	
23	// Repository is a local clone of a GitOps repository, cached between runs and
24	// held under an exclusive lock for the duration of one.
25	type Repository struct {
26		// Root is the checkout directory.
27		Root string
28	
29		// URL is the remote this was cloned from.
30		URL string
31	
32		// Branch is the remote's default branch, the branch deploys land on.
33		Branch string
34	
35		Git git.Client
36	
37		lock *os.File
38	}
39	
40	// RemoteName is the remote deploys read from and push to.
41	const RemoteName = "origin"
42	
43	// Options configures Open.
44	type Options struct {
45		// URL is the GitOps repository to clone. Required.
46		URL string
47	
48		// Runner runs git. Defaults to ExecRunner.
49		Runner command.Runner
50	
51		// CacheRoot overrides where checkouts are cached. Defaults to
52		// <user cache dir>/intropy/gitops. Injectable so tests can redirect the
53		// cache without reaching for HOME — on macOS os.UserCacheDir derives from
54		// it, and overriding HOME makes every git invocation pay a multi-second
55		// penalty for a home directory that does not match the passwd entry.
56		CacheRoot string
57	}
58	
59	// Open returns a clean, up-to-date checkout of the GitOps repository.
60	//
61	// The checkout is cached and reused across runs, so a deploy does not pay for a
62	// full clone every time. Because it is shared, three things are non-negotiable:
63	// an exclusive lock for the whole run, a hard reset rather than a merge on
64	// refresh, and removal of untracked files. A previous run killed part-way
65	// through an edit must not be able to leak that edit into this one's commit.
66	//
67	// The caller must Close the result.
68	func Open(ctx context.Context, opts Options) (*Repository, error) {
69		if opts.URL == "" {
70			return nil, errors.New("no GitOps repository URL")
71		}
72		r := opts.Runner
73		if r == nil {
74			r = command.ExecRunner{}
75		}
76		url := opts.URL
77	
78		cacheRoot := opts.CacheRoot
79		if cacheRoot == "" {
80			var err error
81			if cacheRoot, err = defaultCacheRoot(); err != nil {
82				return nil, err
83			}
84		}
85		dir := CheckoutDir(cacheRoot, url)
86		if err := os.MkdirAll(filepath.Dir(dir), 0o755); err != nil {
87			return nil, fmt.Errorf("create cache directory: %w", err)
88		}
89	
90		lock, err := acquireLock(dir + ".lock")
91		if err != nil {
92			return nil, err
93		}
94	
95		wt := &Repository{Root: dir, URL: url, lock: lock}
96		wt.Git = git.Client{Runner: r, Dir: dir}
97	
98		if err := wt.refresh(ctx, r); err != nil {
99			wt.Close()
100			return nil, err
101		}
102		return wt, nil
103	}
104	
105	func (w *Repository) refresh(ctx context.Context, r command.Runner) error {
106		if _, err := os.Stat(filepath.Join(w.Root, ".git")); err != nil {
107			if !errors.Is(err, fs.ErrNotExist) {
108				return fmt.Errorf("inspect %s: %w", w.Root, err)
109			}
110			// A directory without .git is the debris of an interrupted clone;
111			// git clone refuses to write into it, so clear it first.
112			if err := os.RemoveAll(w.Root); err != nil {
113				return fmt.Errorf("clear %s: %w", w.Root, err)
114			}
115			if err := git.Clone(ctx, r, w.URL, w.Root); err != nil {
116				return err
117			}
118		}
119	
120		branch, err := w.Git.DefaultBranch(ctx, RemoteName)
121		if err != nil {
122			return err
123		}
124		w.Branch = branch
125	
126		if err := w.Git.Fetch(ctx, RemoteName, branch); err != nil {
127			return err
128		}
129		// Hard reset, not pull: the cache has no local history worth preserving,
130		// and a merge could leave conflict markers in a file we are about to
131		// commit.
132		if err := w.Git.ResetHard(ctx, RemoteName+"/"+branch); err != nil {
133			return err
134		}
135		return w.Git.Clean(ctx)
136	}
137	
138	// Close releases the lock. The checkout itself is deliberately kept.
139	func (w *Repository) Close() error {
140		if w.lock == nil {
141			return nil
142		}
143		err := syscall.Flock(int(w.lock.Fd()), syscall.LOCK_UN)
144		if cerr := w.lock.Close(); err == nil {
145			err = cerr
146		}
147		w.lock = nil
148		return err
149	}
150	
151	func defaultCacheRoot() (string, error) {
152		base, err := os.UserCacheDir()
153		if err != nil {
154			return "", fmt.Errorf("locate cache directory: %w", err)
155		}
156		return filepath.Join(base, "intropy", "gitops"), nil
157	}
158	
159	// CachedRoot returns the existing cached checkout for the configured GitOps
160	// repository.
161	//
162	// It never clones or fetches. This backs shell completion, which has to be
163	// instant and must not touch the network — an unconfigured or not-yet-cloned
164	// repository simply yields no suggestions.
165	func CachedRoot(gitopsRepoOverride string) (string, error) {
166		cfg, err := config.Load()
167		if err != nil {
168			return "", err
169		}
170		url, err := cfg.Resolve(config.Flags{GitopsRepo: gitopsRepoOverride}).RequireGitopsRepo()
171		if err != nil {
172			return "", err
173		}
174		cacheRoot, err := defaultCacheRoot()
175		if err != nil {
176			return "", err
177		}
178		dir := CheckoutDir(cacheRoot, url)
179		if _, err := os.Stat(filepath.Join(dir, ".git")); err != nil {
180			return "", fmt.Errorf("no cached checkout of %s yet", url)
181		}
182		return dir, nil
183	}
184	
185	// CheckoutDir derives a stable cache path from the remote URL. The URL is
186	// hashed rather than sanitised because the same repository can be named several
187	// ways (SSH, HTTPS, with or without .git) and because URLs contain characters
188	// that are awkward in paths.
189	func CheckoutDir(cacheRoot, url string) string {
190		sum := sha256.Sum256([]byte(url))
191		return filepath.Join(cacheRoot, hex.EncodeToString(sum[:])[:16])
192	}
193	
194	// acquireLock takes an exclusive, non-blocking lock. Non-blocking on purpose:
195	// two concurrent deploys sharing one checkout would interleave edits, and
196	// telling the user to wait is far better than silently queueing behind a run
197	// that may itself be stuck on a network operation.
198	func acquireLock(path string) (*os.File, error) {
199		f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o644)
200		if err != nil {
201			return nil, fmt.Errorf("open lock file %s: %w", path, err)
202		}
203		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
204			f.Close()
205			if errors.Is(err, syscall.EWOULDBLOCK) {
206				return nil, fmt.Errorf("another intropy deploy is already using the cached GitOps checkout (%s); wait for it to finish", filepath.Dir(path))
207			}
208			return nil, fmt.Errorf("lock %s: %w", path, err)
209		}
210		return f, nil
211	}
