1	// Package command runs external programs behind an interface.
2	//
3	// It exists so that callers of git and kustomize can be tested without either
4	// binary present, and so that every subprocess in this repository is
5	// context-aware by construction.
6	package command
7	
8	import (
9		"bytes"
10		"context"
11		"errors"
12		"fmt"
13		"os/exec"
14		"strings"
15	)
16	
17	// Runner runs an external command. It exists so the git and kustomize call
18	// sites can be tested without either binary present, and so every subprocess
19	// in this package is context-aware by construction.
20	type Runner interface {
21		// Run executes name with args in dir, returning its captured stdout and
22		// stderr. A non-zero exit is an error; stdout and stderr are still
23		// returned so callers can inspect them.
24		Run(ctx context.Context, dir, name string, args ...string) (stdout, stderr []byte, err error)
25	}
26	
27	// ErrNotInstalled reports that a required external binary is not on PATH. It
28	// maps to exit code 127.
29	var ErrNotInstalled = errors.New("not installed")
30	
31	// NotInstalledError names the missing binary and how to get it.
32	type NotInstalledError struct {
33		Binary string
34		Hint   string
35	}
36	
37	func (e *NotInstalledError) Error() string {
38		if e.Hint != "" {
39			return fmt.Sprintf("%s is not installed or not on PATH (%s)", e.Binary, e.Hint)
40		}
41		return fmt.Sprintf("%s is not installed or not on PATH", e.Binary)
42	}
43	
44	func (e *NotInstalledError) Unwrap() error { return ErrNotInstalled }
45	
46	// ExitError reports a command that ran and failed. Stderr is carried verbatim
47	// because git and kustomize both explain themselves well and paraphrasing
48	// their messages loses detail.
49	type ExitError struct {
50		Name   string
51		Args   []string
52		Dir    string
53		Code   int
54		Stderr string
55	}
56	
57	func (e *ExitError) Error() string {
58		msg := strings.TrimSpace(e.Stderr)
59		cmd := e.Name + " " + strings.Join(e.Args, " ")
60		if msg == "" {
61			return fmt.Sprintf("%s: exit status %d", cmd, e.Code)
62		}
63		return fmt.Sprintf("%s: %s", cmd, msg)
64	}
65	
66	// ExecRunner runs commands as subprocesses.
67	type ExecRunner struct{}
68	
69	// Run implements Runner using exec.CommandContext, so cancelling ctx kills the
70	// child. That matters here: this package shells out to `git push` over SSH and
71	// can sit in an ArgoCD poll for minutes, and with a context-free exec.Command a
72	// Ctrl-C would cancel the Go side while the subprocess kept running.
73	func (ExecRunner) Run(ctx context.Context, dir, name string, args ...string) ([]byte, []byte, error) {
74		cmd := exec.CommandContext(ctx, name, args...)
75		cmd.Dir = dir
76	
77		var stdout, stderr bytes.Buffer
78		cmd.Stdout = &stdout
79		cmd.Stderr = &stderr
80	
81		err := cmd.Run()
82		if err != nil {
83			// A cancelled context is the user interrupting; report that rather
84			// than the subprocess's incidental "signal: killed".
85			if ctxErr := ctx.Err(); ctxErr != nil {
86				return stdout.Bytes(), stderr.Bytes(), ctxErr
87			}
88			if errors.Is(err, exec.ErrNotFound) {
89				return stdout.Bytes(), stderr.Bytes(), &NotInstalledError{Binary: name}
90			}
91			if ee, ok := errors.AsType[*exec.ExitError](err); ok {
92				return stdout.Bytes(), stderr.Bytes(), &ExitError{
93					Name:   name,
94					Args:   args,
95					Dir:    dir,
96					Code:   ee.ExitCode(),
97					Stderr: stderr.String(),
98				}
99			}
100			return stdout.Bytes(), stderr.Bytes(), fmt.Errorf("run %s: %w", name, err)
101		}
102		return stdout.Bytes(), stderr.Bytes(), nil
103	}
104	
105	// RequireBinaries checks that every named binary is on PATH, so a run fails
106	// immediately with one clear message naming all of them rather than part-way
107	// through after the worktree has already been mutated.
108	func RequireBinaries(names ...string) error {
109		var missing []string
110		for _, n := range names {
111			if _, err := exec.LookPath(n); err != nil {
112				missing = append(missing, n)
113			}
114		}
115		switch len(missing) {
116		case 0:
117			return nil
118		case 1:
119			return &NotInstalledError{Binary: missing[0], Hint: binaryHints[missing[0]]}
120		default:
121			return fmt.Errorf("%w: %s", ErrNotInstalled, strings.Join(missing, ", "))
122		}
123	}
124	
125	var binaryHints = map[string]string{
126		"git":       "install git",
127		"kustomize": "install kustomize, e.g. brew install kustomize",
128	}
