153	// Init scaffolds a system's manifests into the GitOps repository.
154	//
155	// The sequencing matters more than it looks. The topology is resolved *before*
156	// the session is opened, because openSession takes a non-blocking exclusive lock
157	// on the shared cached checkout and the graph verb can take minutes on a cold
158	// project — holding the lock across that would fail every colleague's deploy
159	// outright. Nothing is written until every file has been classified, and nothing
160	// is pushed to the default branch: a tree full of placeholders would be picked up
161	// by the ApplicationSet immediately.
162	func Init(ctx context.Context, opts InitOptions) error {
163		opts.applyDefaults()
164		out := opts.output()
165	
166		found, err := resolveInitTopology(ctx, opts)
167		if err != nil {
168			return err
169		}
170	
171		s, err := openSession(ctx, opts.session(), "git")
172		if err != nil {
173			return err
174		}
175		defer s.Close()
176	
177		facts, err := newInitFacts(opts, s, found)
178		if err != nil {
179			return err
180		}
181	
182		staging, err := os.MkdirTemp("", "intropy-deploy-init-*")
183		if err != nil {
184			return fmt.Errorf("create staging directory: %w", err)
185		}
186		defer os.RemoveAll(staging)
187	
188		libraryRef, err := renderScaffold(ctx, opts, facts, staging)
189		if err != nil {
190			return err
191		}
192		branch := initBranchPrefix + facts.Domain + "-" + facts.System
193	
194		rels, err := stageRels(staging)
195		if err != nil {
196			return err
197		}
198		actions, err := classifyStaged(staging, s.repo.Root, rels, opts.Force)
199		if err != nil {
200			return err
201		}
202		if opts.Force {
203			if err := assertForceIsSafe(s.repo.Root, actions); err != nil {
204				return err
205			}
206		}
207	
208		result := InitResult{
209			System:       facts.System,
210			Domain:       facts.Domain,
211			Host:         HostDirName,
212			Template:     libraryRef,
213			Components:   facts.ComponentNames(),
214			Files:        actions,
215			Applied:      false,
216			Placeholders: nil,
217		}
218	
219		if opts.PlanOnly {
220			// Scan the staging tree: the files are not in the repository yet, so the
221			// only place the placeholders exist is where they were rendered.
222			result.Placeholders, err = scanPlaceholders(staging, rels)
223			if err != nil {
224				return err
225			}
226			return reportInit(out, result, actions, true)
227		}
228	
229		if writes(actions) == 0 {
230			// Nothing to write, but the placeholders already in the repository are
231			// still the answer to "what is left to do here".
232			result.Placeholders, err = scanPlaceholders(s.repo.Root, rels)
233			if err != nil {
234				return err
235			}
236			return reportInit(out, result, actions, false)
237		}
238	
239		published, err := publishScaffold(ctx, opts, s.repo, publishScaffoldOptions{
240			StagingDir: staging,
241			Actions:    actions,
242			Rels:       rels,
243			Branch:     branch,
244			Facts:      facts,
245		})
246		if err != nil {
247			return err
248		}
249		result.Applied = true
250		result.Branch = branch
251		result.Revision = published.Revision
252		result.Placeholders = published.Placeholders
253	
254		return reportInit(out, result, actions, false)
255	}
256	
257	func writes(actions []FileAction) int {
258		n := 0
259		for _, a := range actions {
260			if a.Writes() {
261				n++
262			}
263		}
264		return n
265	}
266	
267	// discoveredTopology is what resolveInitTopology found in the workspace.
268	type discoveredTopology struct {
269		Topology  *topology.Topology
270		Scaffolds []template.ScaffoldEntry
271	
272		// HostDir is the system host the record came from, empty when --topology
273		// supplied it instead. Its path is the best source for the domain.
274		HostDir string
275	}
276	
277	// resolveInitTopology obtains the record and the workspace's scaffold records.
278	//
279	// A file beats the graph verb: it is how CI avoids paying for a dotnet build, and
280	// how tests avoid needing dotnet at all.
281	func resolveInitTopology(ctx context.Context, opts InitOptions) (discoveredTopology, error) {
282		scaffolds, warnings := template.ListScaffolds(opts.SourceDir)
283		for _, w := range warnings {
284			fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
285		}
286	
287		if opts.TopologyFile != "" {
288			r := opts.Stdin
289			if opts.TopologyFile != "-" {
290				f, err := os.Open(opts.TopologyFile)
291				if err != nil {
292					return discoveredTopology{}, fmt.Errorf("read --topology: %w", err)
293				}
294				defer f.Close()
295				r = f
296			}
297			topo, err := topology.Decode(r)
298			if err != nil {
299				return discoveredTopology{}, fmt.Errorf("read --topology %s: %w", opts.TopologyFile, err)
300			}
301			return discoveredTopology{Topology: topo, Scaffolds: scaffolds}, nil
302		}
303	
304		var hosts []template.ScaffoldEntry
305		for _, s := range scaffolds {
306			if s.Role == template.RoleSystemHost {
307				hosts = append(hosts, s)
308			}
309		}
310		host, err := selectHost(hosts, opts.System, opts.SourceDir)
311		if err != nil {
312			return discoveredTopology{}, err
313		}
314	
