874		if err := repo.Git.CreateBranch(ctx, p.Branch, start); err != nil {
875			return publishedScaffold{}, err
876		}
877		// Unconditionally, on success and on failure alike: the refresh on the next
878		// Open resets whatever branch is current to the default branch's remote head,
879		// so leaving the checkout here would silently discard these commits.
880		defer func() {
881			if err := repo.Git.Switch(ctx, repo.Branch); err != nil {
882				fmt.Fprintf(opts.Stderr, "warning: could not restore %s in the cached checkout: %v\n", repo.Branch, err)
883			}
884		}()
885	
886		written, err := applyStaged(p.StagingDir, repo.Root, p.Actions)
887		if err != nil {
888			return publishedScaffold{}, err
889		}
890		// Only the paths staged, never `add -A`: the checkout is shared, and a
891		// concurrent run's debris is not ours to commit.
892		if err := repo.Git.Add(ctx, written...); err != nil {
893			return publishedScaffold{}, err
894		}
895		if err := repo.Git.Commit(ctx, scaffoldSubject(p.Facts, len(written)), scaffoldTrailers(p.Facts, opts.CliVersion)); err != nil {
896			return publishedScaffold{}, err
897		}
898		if err := repo.Git.Push(ctx, gitops.RemoteName, "HEAD:refs/heads/"+p.Branch); err != nil {
899			return publishedScaffold{}, fmt.Errorf("push %s: %w\n\nA rejection here usually means the branch already exists on the remote. Delete it, or merge the open review first.", p.Branch, err)
900		}
901	
902		revision, err := repo.Git.HEAD(ctx)
903		if err != nil {
904			return publishedScaffold{}, err
905		}
906		// While the branch is still current — the deferred switch above takes these
907		// files back out of the working tree.
908		placeholders, err := scanPlaceholders(repo.Root, p.Rels)
909		if err != nil {
910			return publishedScaffold{}, err
911		}
912		return publishedScaffold{Revision: revision, Placeholders: placeholders}, nil
913	}
