// assertCommitIsExactly checks that staging expected produced a commit of exactly
// expected, and nothing else.
//
// Every caller in this package stages a named list of paths and never `add -A`,
// which is what lets a deployment commit be read as a statement about one
// component. That property is worth verifying rather than assuming: the checkout
// is shared, git runs code the repository supplies while building a commit, and
// the difference between what was asked for and what was recorded is one command
// away.
//
// Called twice, because the two answers are different: once on the index, where a
// surprise can still be investigated, and once on the commit, which is the last
// moment before a push makes it everyone's.
func assertCommitIsExactly(ctx context.Context, g git.Client, expected []string) error {
	staged, err := g.StagedPaths(ctx)
	if err != nil {
		return err
	}
	if err := assertOnly("staged", expected, staged); err != nil {
		return err
	}

	head, err := g.HEAD(ctx)
	if err != nil {
		return err
	}
	committed, err := g.CommitPaths(ctx, head)
	if err != nil {
		return err
	}
	return assertOnly("committed", expected, committed)
}

