//
// Both halves are checked, because they answer different questions at different
// moments. The index is what the commit is about to be made from, and the commit
// is what a push would publish — a hook runs in between, so neither answer implies
// the other.

// assertStagedIsExactly checks the index just before a commit is made from it.
func assertStagedIsExactly(ctx context.Context, g git.Client, expected []string) error {
	staged, err := g.StagedPaths(ctx)
	if err != nil {
		return err
	}
	return assertOnly("staged", expected, staged)
}

// assertCommittedIsExactly checks HEAD, which is the last moment before a push
// makes it everyone's.
//
// It has to run after the commit rather than instead of the staged check: once the
// commit exists the index matches HEAD and has nothing left to report.
func assertCommittedIsExactly(ctx context.Context, g git.Client, expected []string) error {
	head, err := g.HEAD(ctx)
	if err != nil {
		return err
	}
	committed, err := g.CommitPaths(ctx, head)
	if err != nil {
		return err
	}
	return assertOnly("committed", expected, committed)
}

